/**
 * Security middleware for Express.js application
 * Implements various security best practices
 */

// Import security middleware packages
// Note: These need to be installed via npm
// npm install helmet express-rate-limit

const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

/**
 * Apply security headers using Helmet
 * Protects against various attacks by setting HTTP headers
 */
const securityHeaders = helmet({
  // Use HTTPS in production
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true,
  },
  // Prevent clickjacking
  frameguard: {
    action: 'deny',
  },
  // Enable XSS protection
  xssFilter: true,
  // Prevent sniffing of MIME types
  noSniff: true,
  // Remove the X-Powered-By header
  hidePoweredBy: true,
});

/**
 * Rate limiting to prevent abuse and DoS attacks
 * Limits each IP to 100 requests per 15 minutes
 */
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.',
  },
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

/**
 * Input validation middleware
 * This is a template for input validation that can be customized
 */
const validateInput = (req, res, next) => {
  // Implement input validation logic here
  // This is a placeholder that can be expanded based on specific needs
  next();
};

/**
 * Error handling middleware
 * Centralized error handling to prevent information disclosure
 */
const errorHandler = (err, req, res, next) => {
  console.error(err.stack);

  // Don't leak sensitive error information in production
  res.status(500).json({
    error: 'Internal server error',
  });
};

module.exports = {
  securityHeaders,
  limiter,
  validateInput,
  errorHandler,
};

