  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

// Apply rate limiting to all requests
app.use(limiter);

// Health check endpoint (no authentication required)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    version: process.env.npm_package_version || '1.0.0'
  });
});

// Authentication middleware
const authenticate = (req, res, next) => {
  // In a real application, you would validate a JWT, API key, or session
  const authHeader = req.headers['authorization'];

  // For this example, we'll use a simple API key
  // In production, use proper authentication (OAuth, JWT, etc.)
  const apiKey = process.env.API_KEY || 'your-secret-api-key';

  if (authHeader && authHeader === `Bearer ${apiKey}`) {
    next();
  } else {
    res.status(401).json({ 
      error: 'Unauthorized',
      message: 'Authentication is required to access this resource' 
    });
  }
};

// Users endpoint - protected with authentication
app.get('/users', authenticate, (req, res) => {
  // In a real application, this data would come from a database
  // and you might want to implement authorization to ensure 
  // users can only access their own data
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Error handling middleware
// This should be defined after all routes

// Handle 404 - Page Not Found
app.use((req, res, next) => {
  res.status(404).json({ 
    error: 'Not Found',
    message: `The requested route ${req.method} ${req.url} does not exist` 
  });
});

// Handle 500 - Internal Server Error
app.use((err, req, res, next) => {
  // Log the error (in production, you might want to use a logging service)
  console.error('Error:', err.stack);

  // Send generic error message in production
  const errorResponse = {
    error: 'Internal Server Error',
    message: process.env.NODE_ENV === 'production' ? 
      'Something went wrong!' : 
      err.message
  };

  // Add stack trace only in development
  if (process.env.NODE_ENV !== 'production') {
    errorResponse.stack = err.stack;
  }

  res.status(500).json(errorResponse);
});

// Use environment variable for port, with fallback
const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

